grant usage on schema private to authenticated;
grant select, insert, update on table private.customer_account_controls to authenticated;
grant select, insert on table private.customer_security_events to authenticated;
drop policy if exists customer_account_controls_admin_select on private.customer_account_controls;
create policy customer_account_controls_admin_select on private.customer_account_controls for select to authenticated using (private.is_admin());
drop policy if exists customer_account_controls_admin_insert on private.customer_account_controls;
create policy customer_account_controls_admin_insert on private.customer_account_controls for insert to authenticated with check (private.is_admin());
drop policy if exists customer_account_controls_admin_update on private.customer_account_controls;
create policy customer_account_controls_admin_update on private.customer_account_controls for update to authenticated using (private.is_admin()) with check (private.is_admin());
drop policy if exists customer_security_events_admin_select on private.customer_security_events;
create policy customer_security_events_admin_select on private.customer_security_events for select to authenticated using (private.is_admin());
drop policy if exists customer_security_events_admin_insert on private.customer_security_events;
create policy customer_security_events_admin_insert on private.customer_security_events for insert to authenticated with check (private.is_admin());
alter function public.admin_warn_customer(uuid,uuid,text) security invoker;
alter function public.admin_set_customer_blocked(uuid,boolean,text) security invoker;
alter function public.admin_get_user_security_summary(uuid[]) security invoker;
revoke all on function public.admin_warn_customer(uuid,uuid,text) from public, anon;
revoke all on function public.admin_set_customer_blocked(uuid,boolean,text) from public, anon;
revoke all on function public.admin_get_user_security_summary(uuid[]) from public, anon;
grant execute on function public.admin_warn_customer(uuid,uuid,text) to authenticated;
grant execute on function public.admin_set_customer_blocked(uuid,boolean,text) to authenticated;
grant execute on function public.admin_get_user_security_summary(uuid[]) to authenticated;